import { Command, CommanderError } from "commander";
import { TOOL_VERSION } from "./core/types.js";
import { DesignSyncError } from "./core/errors.js";
import { resolveRoot } from "./storage/paths.js";
import { loadFigmaEnvironment } from "./storage/environment.js";
import { loadState } from "./storage/state.js";
import { FigmaProvider } from "./providers/figma.js";
import { scan, status } from "./commands/observe.js";
import { buildAgentPlan } from "./commands/agent.js";
import {
  init,
  register,
  sync,
  migrate,
  installedCli,
} from "./commands/mutate.js";
import {
  formatReport,
  formatChanges,
  formatAgentPlan,
} from "./output/human.js";
import { successEnvelope, errorEnvelope } from "./output/json.js";
const program = new Command();
const jsonMode = process.argv.includes("--json");
let commandName = "unknown";
program
  .name("design-sync")
  .description("Track explicit design/code synchronization baselines.")
  .option("--json", "Print one JSON document")
  .option("--root <path>", "Repository root")
  .exitOverride()
  .configureOutput({
    writeOut: (text) => {
      if (!jsonMode) process.stdout.write(text);
    },
    writeErr: (text) => {
      if (!jsonMode) process.stderr.write(text);
    },
  });
async function run(
  name: string,
  action: (
    root: string,
  ) => Promise<{ result: unknown; human?: string; exitCode?: number }>,
) {
  commandName = name;
  const root = await resolveRoot(program.opts<{ root?: string }>().root);
  await loadFigmaEnvironment(root);
  const { result, human, exitCode } = await action(root);
  process.stdout.write(
    jsonMode
      ? JSON.stringify(successEnvelope(name, result)) + "\n"
      : (human ?? JSON.stringify(result, null, 2)) + "\n",
  );
  process.exitCode = exitCode ?? 0;
}
program
  .command("init")
  .option("--file <key>", "Figma file key for new config")
  .option("--tracking-roots <ids>", "Comma-separated discovery roots")
  .option(
    "--agent <agent>",
    "Install optional codex, claude, or cursor workflow",
  )
  .action((options) =>
    run("init", async (root) => ({
      result: await init(root, options, installedCli),
    })),
  );
program
  .command("register")
  .requiredOption("--node <id>")
  .requiredOption(
    "--files <paths>",
    "Comma-separated repository-relative files",
  )
  .option("--route <route>")
  .option("--story <story>")
  .option("--test <test>")
  .option("--name <name>")
  .option("--replace")
  .action((options) =>
    run("register", async (root) => ({
      result: await register(root, options),
    })),
  );
program
  .command("scan")
  .option("--all", "Show every tracked node in human output")
  .action((options) =>
    run("scan", async (root) => {
      const result = await scan(root, new FigmaProvider());
      return {
        result,
        human: formatReport(result, { showAll: Boolean(options.all) }),
      };
    }),
  );
program
  .command("status")
  .option("--refresh")
  .option("--all", "Show every tracked node in human output")
  .action((options) =>
    run("status", async (root) => {
      const result = options.refresh
        ? await scan(root, new FigmaProvider())
        : await status(root);
      return {
        result,
        human: formatReport(result, { showAll: Boolean(options.all) }),
      };
    }),
  );
program
  .command("agent-plan")
  .description(
    "Prepare an approval-gated agent mapping handoff without starting an agent",
  )
  .option("--refresh")
  .action((options) =>
    run("agent-plan", async (root) => {
      const report = options.refresh
        ? await scan(root, new FigmaProvider())
        : await status(root);
      const result = buildAgentPlan(report);
      return { result, human: formatAgentPlan(result) };
    }),
  );
program
  .command("diff")
  .argument("[node-id]")
  .option("--node <id>")
  .option("--refresh")
  .action((argument, options) =>
    run("diff", async (root) => {
      if (argument && options.node && argument !== options.node)
        throw new DesignSyncError(
          "INVALID_ARGUMENT",
          "Positional node and --node must agree.",
        );
      const id = options.node ?? argument;
      if (!id)
        throw new DesignSyncError(
          "NODE_REQUIRED",
          "Specify a node ID or --node <id>.",
        );
      const report = options.refresh
        ? await scan(root, new FigmaProvider())
        : await status(root);
      const node = report.nodes.find((n) => n.nodeId === id);
      if (!node)
        throw new DesignSyncError(
          "NODE_NOT_TRACKED",
          `Node ${id} is not in the observation. Include or register it and scan.`,
        );
      if (!node.baselineDesignRevision)
        throw new DesignSyncError(
          "BASELINE_MISSING",
          "No synchronized baseline exists for this node. Register, implement, verify, then explicitly sync it.",
        );
      if (
        node.reasons.some((reason) =>
          [
            "DESIGN_MISSING",
            "OBSERVATION_MISSING",
            "CORRUPT_OR_INCOMPATIBLE_SNAPSHOT",
          ].includes(reason),
        )
      )
        throw new DesignSyncError(
          "DIFF_UNAVAILABLE",
          "Cannot compute a reliable diff.",
          { reasons: node.reasons },
        );
      return {
        result: {
          ...node,
          observedAt: report.observedAt,
          freshness: report.freshness,
        },
        human: `${node.name}\n\n${node.changes.length} changes\n\n${formatChanges(node.changes)}`,
      };
    }),
  );
program
  .command("sync")
  .requiredOption("--node <id>")
  .action((options) =>
    run("sync", async (root) => {
      const result = await sync(root, options.node, new FigmaProvider());
      return {
        result,
        human: `✓ ${result.name} synchronized\n\nDesign ${result.designRevision}\nCode   ${result.codeRevision}`,
      };
    }),
  );
program
  .command("check")
  .option("--all", "Show every tracked node in human output")
  .action((options) =>
    run("check", async (root) => {
      const result = await scan(root, new FigmaProvider());
      const { config } = await loadState(root);
      return {
        result,
        human: formatReport(result, { showAll: Boolean(options.all) }),
        exitCode: result.nodes.some((node) =>
          config.ci.failOn.includes(node.status),
        )
          ? 1
          : 0,
      };
    }),
  );
program
  .command("migrate")
  .option("--apply", "Apply supported migrations; default previews")
  .action((options) =>
    run("migrate", async (root) => ({
      result: await migrate(root, Boolean(options.apply)),
    })),
  );
program.command("version").action(() =>
  run("version", async () => ({
    result: {
      toolVersion: TOOL_VERSION,
      configVersion: 1,
      manifestVersion: 1,
      snapshotVersion: 1,
      normalizationVersion: 1,
      outputVersion: 1,
    },
    human: `Design Sync ${TOOL_VERSION}\nManifest schema 1`,
  })),
);
async function main() {
  try {
    await program.parseAsync(process.argv);
  } catch (error) {
    if (error instanceof CommanderError && error.exitCode === 0) {
      if (jsonMode)
        process.stdout.write(
          JSON.stringify(
            successEnvelope("help", { help: program.helpInformation() }),
          ) + "\n",
        );
      return;
    }
    const normalized =
      error instanceof CommanderError
        ? new DesignSyncError("INVALID_ARGUMENT", error.message)
        : error;
    const output = errorEnvelope(commandName, normalized);
    process.stdout.write(jsonMode ? JSON.stringify(output) + "\n" : "");
    if (!jsonMode)
      process.stderr.write(`${output.error.code}: ${output.error.message}\n`);
    process.exitCode = 2;
  }
}
void main();

import type { Report } from "../core/schemas.js";

export function buildAgentPlan(report: Report) {
  const mappingCandidates = report.nodes
    .filter(
      (node) =>
        node.status !== "IGNORED" && node.reasons.includes("MAPPING_MISSING"),
    )
    .map((node) => ({
      reference: node.reference,
      nodeId: node.nodeId,
      name: node.name,
      status: node.status,
      ...(node.devStatus !== undefined ? { devStatus: node.devStatus } : {}),
      ...(node.route ? { route: node.route } : {}),
      reasons: node.reasons,
    }));
  const count = mappingCandidates.length;
  const readiness = {
    readyForDev: mappingCandidates.filter(
      (node) => node.devStatus?.type === "READY_FOR_DEV",
    ).length,
    completed: mappingCandidates.filter(
      (node) => node.devStatus?.type === "COMPLETED",
    ).length,
    none: mappingCandidates.filter((node) => node.devStatus === null).length,
    unknown: mappingCandidates.filter((node) => node.devStatus === undefined)
      .length,
  };
  const noun = count === 1 ? "design" : "designs";
  const approvalQuestion =
    count > 0
      ? `Start a design-mapping agent for ${count} ${noun}, including ${readiness.readyForDev} marked Ready for dev? Starting an agent uses your model token allowance. The agent will inspect the repository, prioritize Ready for dev designs, propose and register defensible mappings, leave ambiguous designs unmapped, and will not accept synchronization baselines.`
      : "No unmapped product designs were found, so a mapping agent is not recommended.";
  const promptAfterApproval =
    count > 0
      ? `The user explicitly approved starting a design-mapping agent for ${count} ${noun}. Follow tools/design-sync/agents/workflow.md. Read the repository instructions and run the JSON status workflow. Prioritize nodes whose devStatus.type is READY_FOR_DEV, but report every candidate's readiness. Inspect each MAPPING_MISSING node and the codebase, register only evidence-backed mappings, document unresolved designs, and verify the final status. After implementation and verification, list the exact verified Figma node IDs and ask the separate figmaCompletionApproval.question before changing any node to COMPLETED in Figma. Do not treat mapping approval as Figma-write approval. Do not run design:sync or accept any baseline unless the user separately requests it after reviewing the implementation.`
      : undefined;
  const copyablePrompt =
    count > 0
      ? `Use the repository's Design Sync workflow to prepare agent-assisted mapping. Run pnpm --silent design:agent-plan --json and inspect its ${count} mapping candidates, including ${readiness.readyForDev} marked Ready for dev. Show me the candidate scope and the exact approval.question, clearly stating that starting the mapping agent uses my model token allowance. Do not start, spawn, delegate to, or perform the mapping agent's work until I explicitly approve. After approval, use promptAfterApproval exactly as the mapping agent's task. When implementation and verification finish, list the exact verified node IDs and ask figmaCompletionApproval.question before marking anything COMPLETED in Figma. Mapping approval does not authorize that Figma write. Do not accept synchronization baselines unless I separately request that after review.`
      : undefined;

  return {
    version: 1 as const,
    kind: "design-mapping" as const,
    agentStarted: false as const,
    recommendation:
      count > 0 ? ("START_AGENT" as const) : ("NO_ACTION" as const),
    approval: {
      requiredBeforeAgentStart: count > 0,
      granted: false as const,
      tokenUsageNotice: count > 0,
      question: approvalQuestion,
    },
    figmaCompletionApproval: {
      requiredBeforeWrite: true as const,
      granted: false as const,
      defaultAction: "LEAVE_FIGMA_UNCHANGED" as const,
      cliCanWrite: false as const,
      question:
        "The listed designs have been implemented and verified. Do you want me to mark these exact Figma nodes as Completed? This changes shared Figma state. I will leave them unchanged unless you explicitly approve.",
      instructions:
        "Ask only after implementation and verification. Include each exact fileKey/nodeId and name. If approved, use an available authenticated Figma write tool, read the nodes back, then run a fresh Design Sync scan. If no write tool or permission is available, report that and leave Figma unchanged.",
    },
    mappingCandidateCount: count,
    readiness,
    mappingCandidates,
    ...(copyablePrompt ? { copyablePrompt } : {}),
    ...(promptAfterApproval ? { promptAfterApproval } : {}),
    observation: {
      observedAt: report.observedAt,
      freshness: report.freshness,
    },
  };
}

export type AgentPlan = ReturnType<typeof buildAgentPlan>;

import path from "node:path";
import { fileURLToPath } from "node:url";
import { mkdir, readFile, realpath, writeFile } from "node:fs/promises";
import { z } from "zod";
import { configSchema, cacheSchema, type NodeRecord } from "../core/schemas.js";
import { DesignSyncError } from "../core/errors.js";
import { identity, designRevision, stableSerialize } from "../core/hashing.js";
import { asUnit } from "../core/normalization.js";
import {
  atomicJson,
  loadState,
  statePath,
  withLock,
  loadBaseline,
  readJson,
} from "../storage/state.js";
import { codeRevision, exists, normalizePath } from "../storage/paths.js";
import { migrateFile } from "../storage/migrations.js";
import type { DesignProvider } from "../providers/types.js";
import { configRevision, referenceFor } from "./observe.js";
const commandNames = [
  "init",
  "register",
  "scan",
  "status",
  "agent-plan",
  "diff",
  "sync",
  "check",
  "migrate",
  "version",
];
export async function init(
  root: string,
  options: { file?: string; trackingRoots?: string; agent?: string },
  cliPath: string,
) {
  if (options.agent && !["codex", "claude", "cursor"].includes(options.agent))
    throw new DesignSyncError(
      "INVALID_AGENT",
      "Choose codex, claude, or cursor.",
    );
  const warnings: string[] = [];
  return withLock(root, async () => {
    const configFile = statePath(root, "config.json");
    if (!(await exists(configFile)))
      await atomicJson(
        configFile,
        configSchema.parse({
          version: 1,
          provider: "figma",
          figma: { fileKey: options.file ?? "" },
          tracking: { roots: splitList(options.trackingRoots ?? "") },
        }),
      );
    if (!(await exists(statePath(root, "manifest.json"))))
      await atomicJson(statePath(root, "manifest.json"), {
        version: 1,
        nodes: {},
      });
    const { config } = await loadState(root);
    await mkdir(statePath(root, "snapshots"), { recursive: true });
    const ignore = statePath(root, ".gitignore");
    const oldIgnore = (await exists(ignore))
      ? await readFile(ignore, "utf8")
      : "";
    const rules = ["cache/", "write.lock", "*.tmp"];
    const missing = rules.filter(
      (rule) => !oldIgnore.split(/\r?\n/).includes(rule),
    );
    if (missing.length)
      await writeFile(
        ignore,
        oldIgnore +
          (oldIgnore && !oldIgnore.endsWith("\n") ? "\n" : "") +
          missing.join("\n") +
          "\n",
      );
    const pkgFile = path.join(root, "package.json");
    if (await exists(pkgFile)) {
      const pkg = z
        .object({ scripts: z.record(z.string(), z.string()).optional() })
        .passthrough()
        .parse(JSON.parse(await readFile(pkgFile, "utf8")));
      // Windows can expose the same temporary directory through both a short
      // 8.3 path and its long path. Canonicalize both sides before deriving
      // the repository-relative script path.
      const relativeCli = normalizePath(
        path.relative(await realpath(root), await realpath(cliPath)),
      );
      const scripts = { ...pkg.scripts };
      for (const name of commandNames) {
        const key = `design:${name}`,
          value = `tsx ${JSON.stringify(relativeCli)} ${name}`;
        if (scripts[key] && scripts[key] !== value)
          warnings.push(`Preserved conflicting ${key}. Run directly: ${value}`);
        else scripts[key] = value;
      }
      if (stableSerialize(scripts) !== stableSerialize(pkg.scripts ?? {}))
        await atomicJson(pkgFile, { ...pkg, scripts });
    } else
      warnings.push(
        "No root package.json found. Invoke the installed CLI directly with tsx.",
      );
    if (options.agent) {
      const destinations: Record<string, string> = {
        codex: ".agents/skills/design-sync/SKILL.md",
        claude: ".claude/skills/design-sync/SKILL.md",
        cursor: ".cursor/rules/design-sync.mdc",
      };
      const destination = path.join(root, destinations[options.agent]!);
      const relativeGuide = path
        .relative(
          path.dirname(destination),
          path.join(root, "tools/design-sync/agents/workflow.md"),
        )
        .replaceAll("\\", "/");
      const frontmatter =
        options.agent === "cursor"
          ? "---\ndescription: Design Sync implementation workflow\nalwaysApply: false\n---\n"
          : "---\nname: design-sync\ndescription: Discover design changes, update implementations, verify, then explicitly synchronize one node.\n---\n";
      await mkdir(path.dirname(destination), { recursive: true });
      try {
        await writeFile(
          destination,
          `${frontmatter}\nRead and follow [the canonical workflow](${relativeGuide}).\n`,
          { flag: "wx" },
        );
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
        warnings.push(`Preserved existing agent instructions: ${destination}`);
      }
    }
    if (!config.figma.fileKey)
      warnings.push(
        "Set figma.fileKey in .design-sync/config.json before scanning.",
      );
    if (!process.env.FIGMA_ACCESS_TOKEN)
      warnings.push(
        "Set FIGMA_ACCESS_TOKEN in your shell or .env before live Figma commands.",
      );
    return { root, initialized: true, warnings };
  });
}
export function splitList(value: string) {
  return [
    ...new Set(
      value
        .split(",")
        .map((s) => s.trim())
        .filter(Boolean),
    ),
  ];
}
export async function register(
  root: string,
  options: {
    node: string;
    files: string;
    route?: string;
    story?: string;
    test?: string;
    name?: string;
    replace?: boolean;
  },
) {
  return withLock(root, async () => {
    const { config, manifest } = await loadState(root);
    if (!config.figma.fileKey)
      throw new DesignSyncError(
        "SETUP_REQUIRED",
        "Configure figma.fileKey before registering a node.",
      );
    const files = [
      ...new Set(splitList(options.files).map(normalizePath)),
    ].sort();
    await codeRevision(root, files);
    const reference = referenceFor(config, options.node),
      key = identity(reference),
      previous = manifest.nodes[key];
    const extensions = { ...previous?.implementation };
    for (const field of ["files", "route", "story", "test"])
      delete extensions[field];
    const implementation = {
      ...extensions,
      files,
      ...(options.route !== undefined ? { route: options.route } : {}),
      ...(options.story !== undefined ? { story: options.story } : {}),
      ...(options.test !== undefined ? { test: options.test } : {}),
    };
    const changed =
      previous?.implementation &&
      stableSerialize(previous.implementation) !==
        stableSerialize(implementation);
    if (changed && !options.replace)
      throw new DesignSyncError(
        "DUPLICATE_MAPPING",
        "This node already has a different mapping. Use --replace to change it and invalidate its baseline.",
      );
    const record: NodeRecord = {
      ...previous,
      reference,
      name: options.name ?? previous?.name ?? options.node,
      type: previous?.type ?? "UNKNOWN",
      implementation,
    };
    if (changed) delete record.baseline;
    manifest.nodes[key] = record;
    await atomicJson(statePath(root, "manifest.json"), manifest);
    return {
      reference,
      implementation,
      baselineEstablished: false,
      baselinePreserved: Boolean(record.baseline),
    };
  });
}
export async function sync(
  root: string,
  nodeId: string,
  provider: DesignProvider,
) {
  return withLock(root, async () => {
    const { config, manifest } = await loadState(root);
    const reference = referenceFor(config, nodeId),
      key = identity(reference),
      record = manifest.nodes[key];
    if (config.tracking.exclude.includes(nodeId))
      throw new DesignSyncError(
        "NODE_IGNORED",
        "Remove the node from tracking.exclude before synchronizing.",
      );
    if (!record?.implementation)
      throw new DesignSyncError(
        "MAPPING_REQUIRED",
        "Register implementation files before synchronizing this node.",
      );
    const fetched = await provider.getNode(reference);
    if (!fetched)
      throw new DesignSyncError(
        "DESIGN_MISSING",
        `Figma node ${nodeId} does not exist in file ${reference.fileKey}. Verify its identity; no baseline was changed.`,
      );
    const node = asUnit(fetched);
    if (node.issues.length)
      throw new DesignSyncError(
        "UNSUPPORTED_DESIGN",
        "Design contains unsupported structures; synchronization was refused.",
        { issues: node.issues },
      );
    const design = designRevision(node),
      code = await codeRevision(root, record.implementation.files);
    const snapshot = `snapshots/${key}/${design.slice(7)}.json`;
    const snapshotFile = statePath(root, snapshot);
    if (await exists(snapshotFile))
      await loadBaseline(root, {
        ...record,
        baseline: {
          designRevision: design,
          codeRevision: code,
          snapshot,
          lastSyncedAt: new Date().toISOString(),
        },
      });
    else
      await atomicJson(snapshotFile, {
        version: 1,
        normalizationVersion: 1,
        reference,
        designRevision: design,
        node,
      });
    // Fail before committing if files changed while preparing the snapshot.
    if (code !== (await codeRevision(root, record.implementation.files)))
      throw new DesignSyncError(
        "CODE_CHANGED_DURING_SYNC",
        "Implementation files changed during synchronization. Verify and retry.",
      );
    record.name = node.name;
    record.type = node.type;
    record.baseline = {
      ...record.baseline,
      designRevision: design,
      codeRevision: code,
      snapshot,
      lastSyncedAt: new Date().toISOString(),
    };

    // Keep other nodes and the conservative observation age; never fabricate a full scan.
    const cacheFile = statePath(root, "cache/observation.json");
    const cache = await readJson(cacheFile, cacheSchema).catch(() => undefined);
    if (cache && cache.configRevision === configRevision(config)) {
      cache.nodes[nodeId] = node;
      delete cache.fileVersion; // This cache can now contain observations from different file versions.
      await atomicJson(cacheFile, cache);
    }
    await atomicJson(statePath(root, "manifest.json"), manifest);
    return {
      reference,
      name: node.name,
      synchronized: true,
      ...record.baseline,
    };
  });
}
export async function migrate(root: string, apply: boolean) {
  return withLock(root, async () => {
    // V1 deliberately has no invented historical migration. Unknown versions fail closed.
    const files = ["config.json", "manifest.json"];
    const results = [];
    for (const file of files)
      results.push(await migrateFile(statePath(root, file), 1, [], apply));
    const { manifest } = await loadState(root);
    for (const node of Object.values(manifest.nodes))
      if (node.baseline) await loadBaseline(root, node);
    return {
      applied: apply,
      migrations: results,
      message: "V1 state is current. No migration required.",
    };
  });
}
export const installedCli = fileURLToPath(
  new URL("../cli.ts", import.meta.url),
);

import {
  cacheSchema,
  type Config,
  type Manifest,
  type Report,
  type Cache,
  type NodeResult,
} from "../core/schemas.js";
import { hash, identity, designRevision } from "../core/hashing.js";
import { asUnit } from "../core/normalization.js";
import { classifyStatus } from "../core/classifier.js";
import { diffDesign } from "../core/diff.js";
import { DesignSyncError, errorInfo } from "../core/errors.js";
import type { DesignNode, DesignNodeReference } from "../core/types.js";
import type { DesignProvider } from "../providers/types.js";
import {
  atomicJson,
  loadBaseline,
  loadState,
  readJson,
  statePath,
  withLock,
} from "../storage/state.js";
import { codeRevision } from "../storage/paths.js";
export const referenceFor = (
  config: Config,
  nodeId: string,
): DesignNodeReference => {
  if (!nodeId.trim() || !config.figma.fileKey.trim())
    throw new DesignSyncError(
      "INVALID_REFERENCE",
      "A nonempty Figma file key and node ID are required.",
    );
  return { provider: "figma", fileKey: config.figma.fileKey, nodeId };
};
export function configRevision(config: Config) {
  return hash({
    provider: config.provider,
    figma: config.figma,
    tracking: config.tracking,
  });
}
export function validateTracking(config: Config, manifest: Manifest) {
  if (!config.figma.fileKey)
    throw new DesignSyncError(
      "SETUP_REQUIRED",
      "Set figma.fileKey in .design-sync/config.json.",
    );
  if (
    !config.tracking.roots.length &&
    !config.tracking.include.length &&
    !Object.keys(manifest.nodes).length
  )
    throw new DesignSyncError(
      "TRACKING_REQUIRED",
      "Configure tracking.roots or tracking.include, or register an explicit node. An empty scope never scans the entire file.",
    );
}
export async function observe(
  config: Config,
  manifest: Manifest,
  provider: DesignProvider,
): Promise<Cache> {
  validateTracking(config, manifest);
  const roots = [...new Set(config.tracking.roots)];
  const explicit = [
    ...new Set([
      ...config.tracking.include,
      ...Object.values(manifest.nodes).map((n) => n.reference.nodeId),
    ]),
  ];
  const initialIds = roots.length ? roots : explicit;
  const first = await provider.getNodes(
    initialIds.map((id) => referenceFor(config, id)),
  );
  const all = new Map<string, DesignNode>(),
    selected: Record<string, DesignNode | null> = {};
  function index(node: DesignNode) {
    all.set(node.id, node);
    for (const child of node.children) index(child);
  }
  for (const node of Object.values(first.nodes)) if (node) index(node);
  function discover(node: DesignNode) {
    if (config.tracking.exclude.includes(node.id)) {
      selected[node.id] = asUnit(node);
      return;
    }
    if (
      config.tracking.nodeTypes.includes(
        node.type as Config["tracking"]["nodeTypes"][number],
      )
    ) {
      selected[node.id] = asUnit(node);
      return;
    }
    for (const child of node.children) discover(child);
  }
  for (const id of roots) {
    const node = all.get(id);
    if (!node)
      throw new DesignSyncError(
        "TRACKING_ROOT_MISSING",
        `Tracking root ${id} is missing. Update tracking.roots or restore access.`,
      );
    // Page/section roots are containers; explicit include can track the root itself.
    for (const child of node.children) discover(child);
  }
  const missing = explicit.filter((id) => !all.has(id) && !(id in first.nodes));
  if (missing.length) {
    if (!first.version)
      throw new DesignSyncError(
        "INCONSISTENT_OBSERVATION",
        "Cannot fetch additional nodes without a pinned Figma version.",
      );
    const extra = await provider.getNodes(
      missing.map((id) => referenceFor(config, id)),
      first.version,
    );
    for (const node of Object.values(extra.nodes)) if (node) index(node);
  }
  for (const id of explicit)
    selected[id] = all.has(id) ? asUnit(all.get(id)!) : null;
  // Explicit exclusions that exist under fetched roots remain visible as IGNORED.
  for (const id of config.tracking.exclude)
    if (all.has(id)) selected[id] = asUnit(all.get(id)!);
  return {
    version: 1,
    normalizationVersion: 1,
    configRevision: configRevision(config),
    observedAt: new Date().toISOString(),
    ...(first.version ? { fileVersion: first.version } : {}),
    nodes: selected,
  };
}
export async function buildReport(
  root: string,
  config: Config,
  manifest: Manifest,
  cache: Cache,
  source: "cache" | "live",
): Promise<Report> {
  const result: NodeResult[] = [];
  const ids = [
    ...new Set([
      ...Object.keys(cache.nodes),
      ...Object.values(manifest.nodes).map((n) => n.reference.nodeId),
    ]),
  ].sort();
  for (const id of ids) {
    const reference = referenceFor(config, id),
      record = manifest.nodes[identity(reference)],
      node = cache.nodes[id];
    const reasons: string[] = [],
      changes: NodeResult["changes"] = [];
    const ignored = config.tracking.exclude.includes(id);
    let currentCodeRevision: string | undefined;
    if (!node)
      reasons.push(
        id in cache.nodes ? "DESIGN_MISSING" : "OBSERVATION_MISSING",
      );
    if (node?.issues.length) reasons.push(...node.issues);
    if (record?.implementation) {
      try {
        currentCodeRevision = await codeRevision(
          root,
          record.implementation.files,
        );
      } catch (error) {
        reasons.push(errorInfo(error).code);
      }
    }
    if (record?.baseline) {
      try {
        const baseline = await loadBaseline(root, record);
        if (baseline && node) changes.push(...diffDesign(baseline.node, node));
      } catch {
        reasons.push("CORRUPT_OR_INCOMPATIBLE_SNAPSHOT");
      }
    }
    const currentDesignRevision = node ? designRevision(node) : undefined;
    const status = classifyStatus({
      ignored,
      ambiguous: reasons.length > 0,
      exists: Boolean(node),
      hasMapping: Boolean(record?.implementation),
      baselineDesignRevision: record?.baseline?.designRevision,
      baselineCodeRevision: record?.baseline?.codeRevision,
      currentDesignRevision,
      currentCodeRevision,
    });
    if (ignored) reasons.push("INTENTIONALLY_EXCLUDED");
    else if (!record?.implementation) reasons.push("MAPPING_MISSING");
    else if (!record.baseline) reasons.push("BASELINE_MISSING");
    if (status === "NEEDS_REVIEW" && reasons.length === 0)
      reasons.push("BOTH_CHANGED");
    result.push({
      reference,
      nodeId: id,
      name: node?.name ?? record?.name ?? id,
      status,
      ...(node && "devStatus" in node
        ? { devStatus: node.devStatus ?? null }
        : {}),
      ...(record?.implementation?.route !== undefined
        ? { route: record.implementation.route }
        : {}),
      implementationFiles: record?.implementation?.files ?? [],
      ...(record?.baseline
        ? {
            baselineDesignRevision: record.baseline.designRevision,
            baselineCodeRevision: record.baseline.codeRevision,
          }
        : {}),
      ...(currentDesignRevision ? { currentDesignRevision } : {}),
      ...(currentCodeRevision ? { currentCodeRevision } : {}),
      reasons,
      changes,
    });
  }
  const count = (status: NodeResult["status"]) =>
    result.filter((n) => n.status === status).length;
  return {
    observedAt: cache.observedAt,
    freshness: {
      source,
      ageSeconds: Math.max(
        0,
        Math.floor((Date.now() - Date.parse(cache.observedAt)) / 1000),
      ),
    },
    nodes: result,
    summary: {
      implemented: count("IMPLEMENTED"),
      designChanged: count("DESIGN_CHANGED"),
      notImplemented: count("NOT_IMPLEMENTED"),
      codeChanged: count("CODE_CHANGED"),
      needsReview: count("NEEDS_REVIEW"),
      ignored: count("IGNORED"),
      devStatus: {
        readyForDev: result.filter(
          (node) => node.devStatus?.type === "READY_FOR_DEV",
        ).length,
        completed: result.filter((node) => node.devStatus?.type === "COMPLETED")
          .length,
        none: result.filter((node) => node.devStatus === null).length,
        unknown: result.filter((node) => node.devStatus === undefined).length,
      },
      coverage: {
        active: result.filter((node) => node.status !== "IGNORED").length,
        mappedToCode: result.filter(
          (node) =>
            node.status !== "IGNORED" && node.implementationFiles.length > 0,
        ).length,
        mappedAwaitingBaseline: result.filter(
          (node) =>
            node.status !== "IGNORED" &&
            node.implementationFiles.length > 0 &&
            !node.baselineDesignRevision,
        ).length,
        acceptedBaselines: result.filter(
          (node) =>
            node.status !== "IGNORED" && Boolean(node.baselineDesignRevision),
        ).length,
        unmapped: result.filter(
          (node) =>
            node.status !== "IGNORED" && node.implementationFiles.length === 0,
        ).length,
      },
    },
  };
}
export async function scan(root: string, provider: DesignProvider) {
  return withLock(root, async () => {
    const { config, manifest } = await loadState(root);
    const cache = await observe(config, manifest, provider);
    const report = await buildReport(root, config, manifest, cache, "live");
    await atomicJson(statePath(root, "cache/observation.json"), cache);
    return report;
  });
}
export async function status(root: string) {
  const { config, manifest } = await loadState(root);
  const cache = await readJson(
    statePath(root, "cache/observation.json"),
    cacheSchema,
  ).catch(() => {
    throw new DesignSyncError(
      "SCAN_REQUIRED",
      "No valid cached observation. Run design:scan first.",
    );
  });
  if (cache.configRevision !== configRevision(config))
    throw new DesignSyncError(
      "SCAN_REQUIRED",
      "Tracking configuration changed. Run design:scan to refresh the observation.",
    );
  return buildReport(root, config, manifest, cache, "cache");
}

import type { DesignStatus } from "./types.js";
export type ClassificationInput = {
  ignored?: boolean;
  ambiguous?: boolean;
  exists: boolean;
  hasMapping: boolean;
  baselineDesignRevision?: string;
  baselineCodeRevision?: string;
  currentDesignRevision?: string;
  currentCodeRevision?: string;
};
export function classifyStatus(input: ClassificationInput): DesignStatus {
  if (input.ignored) return "IGNORED";
  if (
    input.ambiguous ||
    !input.exists ||
    !input.currentDesignRevision ||
    (input.hasMapping && !input.currentCodeRevision)
  )
    return "NEEDS_REVIEW";
  const partial =
    Boolean(input.baselineDesignRevision) !==
    Boolean(input.baselineCodeRevision);
  if (
    partial ||
    (!input.hasMapping &&
      (input.baselineDesignRevision || input.baselineCodeRevision))
  )
    return "NEEDS_REVIEW";
  if (!input.hasMapping || !input.baselineDesignRevision)
    return "NOT_IMPLEMENTED";
  const design = input.baselineDesignRevision !== input.currentDesignRevision;
  const code = input.baselineCodeRevision !== input.currentCodeRevision;
  return design && code
    ? "NEEDS_REVIEW"
    : design
      ? "DESIGN_CHANGED"
      : code
        ? "CODE_CHANGED"
        : "IMPLEMENTED";
}

import type { DesignNode, DesignChange } from "./types.js";
import { stableSerialize } from "./hashing.js";
export function diffDesign(
  before: DesignNode,
  after: DesignNode,
): DesignChange[] {
  type Entry = {
    node: DesignNode;
    path: string;
    label: string;
    parent: string | null;
  };
  function index(root: DesignNode) {
    const result = new Map<string, Entry>();
    function walk(
      node: DesignNode,
      path: string,
      label: string,
      parent: string | null,
    ) {
      result.set(node.id, { node, path, label, parent });
      for (const child of node.children)
        walk(child, `${path}/${child.id}`, `${label}/${child.name}`, node.id);
    }
    walk(root, root.id, root.name, null);
    return result;
  }
  const old = index(before),
    current = index(after),
    changes: DesignChange[] = [];
  for (const [id, entry] of old)
    if (!current.has(id) && (!entry.parent || current.has(entry.parent)))
      changes.push({
        type: "REMOVED",
        path: entry.path,
        label: entry.label,
        before: entry.node.type,
      });
  for (const [id, entry] of current) {
    const previous = old.get(id);
    if (!previous) {
      if (!entry.parent || old.has(entry.parent))
        changes.push({
          type: "ADDED",
          path: entry.path,
          label: entry.label,
          after: entry.node.type,
        });
      continue;
    }
    const a = {
      type: previous.node.type,
      parent: previous.parent,
      childOrder: previous.node.children.map((n) => n.id),
      ...previous.node.properties,
    };
    const b = {
      type: entry.node.type,
      parent: entry.parent,
      childOrder: entry.node.children.map((n) => n.id),
      ...entry.node.properties,
    };
    for (const property of [
      ...new Set([...Object.keys(a), ...Object.keys(b)]),
    ].sort()) {
      const left = a[property as keyof typeof a],
        right = b[property as keyof typeof b];
      if (
        stableSerialize({ value: left }) !== stableSerialize({ value: right })
      )
        changes.push({
          type: "MODIFIED",
          path: entry.path,
          label: entry.label,
          property,
          ...(left !== undefined ? { before: left } : {}),
          ...(right !== undefined ? { after: right } : {}),
        });
    }
  }
  return changes;
}

export class DesignSyncError extends Error {
  constructor(
    public readonly code: string,
    message: string,
    public readonly details: Record<string, unknown> = {},
  ) {
    super(message);
    this.name = "DesignSyncError";
  }
}
export function errorInfo(error: unknown) {
  if (error instanceof DesignSyncError)
    return { code: error.code, message: error.message, details: error.details };
  return {
    code: "TOOL_FAILURE",
    message: error instanceof Error ? error.message : String(error),
    details: {},
  };
}

import { createHash } from "node:crypto";
import type { DesignNode, DesignNodeReference } from "./types.js";
export function stableSerialize(value: unknown): string {
  if (value === null || typeof value !== "object") {
    const result = JSON.stringify(value);
    if (result === undefined) throw new TypeError("Cannot serialize undefined");
    return result;
  }
  if (Array.isArray(value)) return `[${value.map(stableSerialize).join(",")}]`;
  const record = value as Record<string, unknown>;
  return `{${Object.keys(record)
    .sort()
    .filter((k) => record[k] !== undefined)
    .map((k) => `${JSON.stringify(k)}:${stableSerialize(record[k])}`)
    .join(",")}}`;
}
export function hash(value: unknown): string {
  return `sha256:${createHash("sha256").update(stableSerialize(value)).digest("hex")}`;
}
export function identity(reference: DesignNodeReference): string {
  return Buffer.from(stableSerialize(reference)).toString("base64url");
}
export function designRevision(node: DesignNode): string {
  function meaningful(n: DesignNode): unknown {
    return {
      id: n.id,
      type: n.type,
      properties: n.properties,
      children: n.children.map(meaningful),
    };
  }
  return hash({ normalizationVersion: 1, node: meaningful(node) });
}

import type { DesignNode } from "./types.js";
/** A tracked unit's position on its containing canvas is display metadata. */
export function asUnit(node: DesignNode): DesignNode {
  const unit = structuredClone(node);
  delete unit.properties.x;
  delete unit.properties.y;
  const transform = unit.properties.transform;
  if (
    Array.isArray(transform) &&
    Array.isArray(transform[0]) &&
    Array.isArray(transform[1])
  ) {
    transform[0][2] = 0;
    transform[1][2] = 0;
  }
  return unit;
}

